    def delete_all_by_username(cls, username, _test=False):
        oldb = get_db()
        t = oldb.transaction()

        try:
            rows_deleted = oldb.delete(
                cls.TABLENAME, where="username=$username", vars={"username": username}
            )
        except (UniqueViolation, IntegrityError):
